+import type { Branch } from './types';
+import seedBranches from '../supabase/seed_branches.json';
+
+export async function loadBranches(): Promise<Branch[]> {
+  try {
+    const { getSupabase } = await import('./supabase');
+    const supabase = getSupabase();
+    if (supabase) {
+      const { data, error } = await supabase
+        .from('branches')
+        .select('id, name, city');
+      if (!error && data && data.length > 0) {
+        return (data as Branch[]).map((b) => ({ id: b.id, name: b.name, city: b.city ?? '' }));
+      }
+    }
+  } catch (e) {
+    console.warn('loadBranches Supabase fallback to seed', e);
+  }
+  return seedBranches as Branch[];
+}
