+import type { ClosingRecord, FinancialFields } from './types';
+
+const LS_KEY = 'm2_closings_queue';
+const BRANCH_KEY = 'm2_branch_session';
+
+export function loadSessionBranch(): { id: string; name: string } | null {
+  try {
+    const raw = typeof window !== 'undefined' ? window.localStorage.getItem(BRANCH_KEY) : null;
+    return raw ? (JSON.parse(raw) as { id: string; name: string }) : null;
+  } catch {
+    return null;
+  }
+}
+
+export function saveSessionBranch(b: { id: string; name: string }) {
+  try {
+    window.localStorage.setItem(BRANCH_KEY, JSON.stringify(b));
+  } catch {
+    /* ignore */
+  }
+}
+
+export function clearSessionBranch() {
+  try {
+    window.localStorage.removeItem(BRANCH_KEY);
+  } catch {
+    /* ignore */
+  }
+}
+
+export function computeShortage(f: FinancialFields): number {
+  return (f.cashActualHanded || 0) - (f.cashSystem || 0);
+}
+
+function readLocal(): ClosingRecord[] {
+  try {
+    const raw = window.localStorage.getItem(LS_KEY);
+    return raw ? (JSON.parse(raw) as ClosingRecord[]) : [];
+  } catch {
+    return [];
+  }
+}
+
+function writeLocal(items: ClosingRecord[]) {
+  try {
+    window.localStorage.setItem(LS_KEY, JSON.stringify(items));
+  } catch {
+    /* ignore */
+  }
+}
+
+function mapRow(row: Record<string, unknown>): ClosingRecord {
+  return {
+    id: String(row.id ?? ''),
+    branchId: String(row.branch_id ?? ''),
+    branchName: String(row.branch_name ?? ''),
+    businessDate: String(row.business_date ?? ''),
+    fields: (row.fields as ClosingRecord['fields']) ?? {
+      cashSystem: 0, cashActualHanded: 0, mada: 0, visa: 0, bankDeposit: 0, expenses: 0,
+    },
+    shortageOrExcess: Number(row.shortage_or_excess ?? 0),
+    status: (row.status as ClosingRecord['status']) ?? 'pending',
+    createdAt: String(row.created_at ?? new Date().toISOString()),
+  };
+}
+
+export async function findExistingClosing(
+  branchId: string,
+  businessDate: string
+): Promise<ClosingRecord | null> {
+  try {
+    const { getSupabase } = await import('./supabase');
+    const supabase = getSupabase();
+    if (supabase) {
+      const { data } = await supabase
+        .from('daily_closings')
+        .select('*')
+        .eq('branch_id', branchId)
+        .eq('business_date', businessDate)
+        .maybeSingle();
+      if (data) return mapRow(data as Record<string, unknown>);
+    }
+  } catch (e) {
+    console.warn('findExistingClosing Supabase failed, using local', e);
+  }
+  const all = readLocal();
+  return all.find((c) => c.branchId === branchId && c.businessDate === businessDate) ?? null;
+}
+
+export async function saveClosing(rec: ClosingRecord): Promise<void> {
+  try {
+    const { getSupabase } = await import('./supabase');
+    const supabase = getSupabase();
+    if (supabase) {
+      const { error } = await supabase.from('daily_closings').upsert({
+        id: rec.id,
+        branch_id: rec.branchId,
+        branch_name: rec.branchName,
+        business_date: rec.businessDate,
+        fields: rec.fields,
+        shortage_or_excess: rec.shortageOrExcess,
+        status: rec.status,
+        manual_actual_cash: rec.manualActualCash ?? null,
+        images: rec.images ?? null,
+        created_at: rec.createdAt,
+      });
+      if (!error) return;
+      console.warn('saveClosing Supabase error', error);
+    }
+  } catch (e) {
+    console.warn('saveClosing fallback to local', e);
+  }
+  const all = readLocal();
+  const idx = all.findIndex(
+    (c) => c.branchId === rec.branchId && c.businessDate === rec.businessDate
+  );
+  if (idx >= 0) all[idx] = rec;
+  else all.push(rec);
+  writeLocal(all);
+}
