```ts
import { ClosingRecord, FinancialFields } from './types';
import seedBranches from '../supabase/seed_branches.json';

const LS_KEY = 'm2_closings_queue';
const BRANCH_KEY = 'm2_branch_session';

export function loadSessionBranch(): { id: string; name: string } | null {
  try {
    const raw = localStorage.getItem(BRANCH_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}
export function saveSessionBranch(b: { id: string; name: string }) {
  localStorage.setItem(BRANCH_KEY, JSON.stringify(b));
}
export function clearSessionBranch() {
  localStorage.removeItem(BRANCH_KEY);
}

export function computeShortage(f: FinancialFields): number {
  return (f.cashActualHanded || 0) - (f.cashSystem || 0);
}

export async function findExistingClosing(branchId: string, businessDate: string): Promise<ClosingRecord | null> {
  // Try Supabase
  try {
    const { getSupabase } = await import('./supabase');
    const supabase = getSupabase();
    if (supabase) {
      const { data } = await supabase
        .from('daily_closings')
        .select('*')
        .eq('branch_id', branchId)
        .eq('business_date', businessDate)
        .maybeSingle();
      if (data) return mapRow(data);
    }
  } catch (e) {
    console.warn('Closing lookup Supabase failed', e);
  }
  // Fallback localStorage
  const all = readLocal();
  return all.find(c => c.branchId === branchId && c.businessDate === businessDate) || null;
}

export async function saveClosing(rec: ClosingRecord): Promise<void> {
  try {
    const { getSupabase } = await import('./supabase');
    const supabase = getSupabase();
    if (supabase) {
      const { error } = await supabase.from('daily_closings').upsert({
        id: rec.id,
        branch_id: rec.branchId,
        branch_name: rec.branchName,
        business_date: rec.businessDate,
        fields: rec.fields,
        shortage_or_excess: rec.shortageOrExcess,
        status: rec.status,
        created_at: rec.createdAt,
      });
      if (!error) return;
      console.warn('saveClosing Supabase error', error);
    }
  } catch (e) {
    console.warn('saveClosing fallback', e);
  }
  const all = readLocal();
  const idx = all.findIndex(c => c.branchId === rec.branchId && c.businessDate === rec.businessDate);
  if (idx >= 0) all[idx] = rec; else all.push(rec);
  writeLocal(all);
}

function readLocal(): ClosingRecord[] {
  try {
    const raw = localStorage.getItem(LS_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch { return []; }
}
function writeLocal(items: ClosingRecord[]) {
  localStorage.setItem(LS_KEY, JSON.stringify(items));
}
function mapRow(row: any): ClosingRecord {
  return {
    id: row.id,
    branchId: row.branch_id,
    branchName: row.branch_name,
    businessDate: row.business_date,
    fields: row.fields,
    shortageOrExcess: row.shortage_or_excess ?? 0,
    status: row.status ?? 'pending',
    createdAt: row.created_at,
  };
}
